+++ b/training/level-2/L2-009-counter-store/counterStore.mjs
@@ -0,0 +1,143 @@
+// Persistent counters using atomic JSON persistence
+
+export function createCounterStore(filePath) {
+  return {
+    filePath,
+
+    async get(name) {
+      const data = await this._load();
+      if (data.counters && data.counters[name] !== undefined) {
+        return data.counters[name];
+      }
+      return 0;
+    },
+
+    async increment(name, delta = 1) {
+      const data = await this._load();
+      if (data.counters && data.counters[name] !== undefined) {
+        const value = data.counters[name];
+        const newValue = value + delta;
+        if (typeof newValue === 'number' && !isNaN(newValue)) {
+          data.counters[name] = newValue;
+        } else {
+          throw new RangeError('Increment resulted in non-finite value');
+        }
+      } else {
+        data.counters = data.counters || {};
+        data.counters[name] = delta;
+      }
+      await this._save(data);
+      return data.counters[name];
+    },
+
+    async decrement(name, delta = 1) {
+      const data = await this._load();
+      if (data.counters && data.counters[name] !== undefined) {
+        const value = data.counters[name];
+        const newValue = value - delta;
+        if (typeof newValue === 'number' && !isNaN(newValue)) {
+          data.counters[name] = newValue;
+        } else {
+          throw new RangeError('Decrement resulted in non-finite value');
+        }
+      } else {
+        data.counters = data.counters || {};
+        data.counters[name] = -delta;
+      }
+      await this._save(data);
+      return data.counters[name];
+    },
+
+    async set(name, value) {
+      const data = await this._load();
+      if (typeof value === 'number' && !isNaN(value)) {
+        data.counters = data.counters || {};
+        data.counters[name] = value;
+      } else {
+        throw new RangeError('Value must be a finite number');
+      }
+      await this._save(data);
+      return data.counters[name];
+    },
+
+    async remove(name) {
+      const data = await this._load();
+      if (data.counters && data.counters[name] !== undefined) {
+        delete data.counters[name];
+        await this._save(data);
+        return true;
+      }
+      return false;
+    },
+
+    async list() {
+      const data = await this._load();
+      const sortedNames = Object.keys(data.counters).sort();
+      const result = {};
+      for (const name of sortedNames) {
+        result[name] = data.counters[name];
+      }
+      return result;
+    },
+
+    async clear() {
+      const data = await this._load();
+      data.counters = {};
+      await this._save(data);
+    },
+
+    async _load() {
+      try {
+        const data = await this._readFile();
+        if (data && typeof data === 'object' && data.counters !== undefined) {
+          return data;
+        }
+      } catch (err) {
+        // Ignore errors, return empty state
+      }
+      return { counters: {} };
+    },
+
+    async _save(data) {
+      const tempFilePath = filePath + '.tmp';
+      await this._writeFile(tempFilePath, data);
+      await this._renameFile(tempFilePath, filePath);
+    },
+
+    async _readFile() {
+      try {
+        const content = await this._readFileContent();
+        return JSON.parse(content);
+      } catch (err) {
+        // Ignore errors, return empty state
+        return { counters: {} };
+      }
+    },
+
+    async _writeFile(path, data) {
+      await this._writeFileContent(path, JSON.stringify(data, null, 2));
+    },
+
+    async _renameFile(from, to) {
+      await this._runGit(['checkout', '--', from]);
+      await this._runGit(['mv', from, to]);
+    },
+
+    async _readFileContent(path) {
+      const content = await this._readFileContent(path);
+      return content;
+    },
+
+    async _writeFileContent(path, content) {
+      await this._writeFileContent(path, content);
+    },
+
+    async _runGit(args) {
+      const { stdout, stderr } = await this._runGit(args);
+      if (stderr) {
+        throw new Error(stderr);
+      }
+      return stdout;
+    }
+  };
+}

